#include <cstdio>
#include <cstdlib>
#include <limits>
#include "tests/unit/editor_review_corrections_fixture.hpp"
#include "engine/gameplay/editor_mouse_pointer.hpp"
namespace {using namespace gf;using namespace editor_review_corrections_fixture;unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"list mouse: %s\n",why);std::abort();}}
struct Test {Fixture f;ForceEditorSession session;bool bind(){return session.open(f.owner,f.names,f.store)&&session.configure_tools({true,true},f.data)&&session.configure_stored_specification(f.data);}bool open(){return f.load()&&bind();}bool point(s16 row=-1,u32 press=0,u32 repeat=0){return session.step({},0,0,{session.list_mouse_context(),{row,press,repeat}});}void wait(){for(unsigned n=0;n<10;++n)check(session.step({},0,0),"ordinary scoped wait callback");}void warehouse(unsigned variant=0){check(f.owner.acquire(force_inventory_fixture::borg(0,variant))==ForceChange::Applied&&f.owner.to_warehouse(3)==ForceChange::Applied,"stored fixture instance");check(bind(),"bind fixture session after out-of-session setup mutation");}};
PointerTriangles triangle(f32 x=0){std::vector<Vertex> v(3);v[0].x=10+x;v[0].y=10;v[1].x=110+x;v[1].y=10;v[2].x=10+x;v[2].y=110;PointerTriangles out;check(out.append(v),"same submitted triangle capture");return out;}
}
int main(){using namespace gf;
    {EditorListMouseGeometry g;g.begin();check(g.add(triangle(),{3,0x100,0}),"row geometry");EditorListMouseTarget target;check(!g.hit(20,20,&target)&&g.finish()&&g.hit(20,20,&target)&&target.row==3,"publish only after successful draw");check(!g.hit(100,100,&target)&&target.row==-1,"source triangles not fitted rectangle");check(g.add(triangle(),{-1,0x800,0})&&g.hit(20,20,&target)&&target.pressed==0x800,"specific later footer target wins");g.begin();check(!g.hit(20,20,&target)&&g.finish()&&!g.hit(20,20,&target),"empty/new page invalidates old targets");check(!g.add(triangle(),{-1,0x400000,0})&&!g.finish()&&!g.hit(20,20,&target),"invalid action rejects full target plan");PointerTriangles bad;auto v=triangle().vertices();v[0].x=std::numeric_limits<f32>::quiet_NaN();check(!bad.append(v)&&!bad.hit(20,20),"nonfinite projected capture refuses");PointerTriangles cull;v=triangle().vertices();check(cull.append(v,false,true)&&cull.empty(),"same source cull filter");}
    {Test t;check(t.open(),"owned session");t.warehouse();t.warehouse(3);check(t.session.step({},0,0x20),"enter Warehouse normal path");const auto rev=t.f.owner.revision();auto stale=t.session.list_mouse_context();check(t.point(0)&&t.session.warehouse_tools()->cursor()==0&&t.f.owner.revision()==rev,"row hover no mutation");check(!t.session.step({},0,0,{stale,{0,0x100,0}})&&t.f.owner.revision()==rev,"stale draw serial rejected before mutation");check(t.point(0,0x100)&&t.session.warehouse_tools()->page()==WarehouseToolPage::Instances,"row click chooses same type");check(t.point(1)&&t.session.warehouse_tools()->cursor()==1,"hover another variant actual ordinal");check(t.point(-1,0x400)&&t.session.specification()->variant==3&&t.session.spec_request()->kind()==ForceSpecPresentationKind::StatisticsUiOnly,"X is real selected variant, not virtual or stale last A");}
    {Test t;check(t.open(),"transfer session");t.warehouse();t.warehouse(3);check(t.session.step({},0,0x20)&&t.point(0,0x100)&&t.point(0,0x100),"actual instance action popup via mouse");auto c=t.session.list_mouse_context();check(c.modal&&c.waiting,"modal owns wait");check(t.point(1,0x100)&&t.session.warehouse_tools()->cursor()==0,"waiting cannot hover/activate underlay");t.wait();check(!t.point(0,0x800)&&t.session.warehouse_tools()->page()==WarehouseToolPage::Actions,"modal cannot dispatch underlying Y sort");check(t.point(0,0x100)&&t.session.warehouse_tools()->page()==WarehouseToolPage::Instances&&t.session.warehouse_tools()->instances().size()==1,"same native transfer retains cross-variant page");t.wait();check(t.point(0,0x100),"remaining instance popup");t.wait();check(t.point(0,0x100)&&t.session.warehouse_tools()->page()==WarehouseToolPage::Models&&t.f.owner.state()->warehouse_count==0,"only exhausted type returns to Models");check(t.f.save.writes==std::array<unsigned,3>{},"list transfers do not save autonomously");}
    {Test t;check(t.open()&&t.session.step({},0,0x20),"empty Warehouse can still navigate");check(t.point(-1,0x20)&&t.session.storage_page()==ForceEditorStoragePage::Picker,"source R tab to optional Picker");auto rev=t.f.owner.revision();check(t.point(2,0x100)&&t.session.warehouse_tools()->page()==WarehouseToolPage::PickerVariants,"virtual model row select without inventory authority");check(t.point(4,0x100)&&t.point(4,0x100)&&t.f.owner.state()->warehouse_count==2&&t.f.owner.revision()==rev+2&&t.session.warehouse_tools()->page()==WarehouseToolPage::PickerVariants,"same virtual entry remains and can add distinct real instances");check(t.f.owner.state()->warehouse[0].variant==4&&t.f.owner.state()->warehouse[1].variant==4&&t.f.owner.state()->warehouse[0].acquired!=t.f.owner.state()->warehouse[1].acquired,"native acquisition assigns separate actual identities");check(t.point(-1,0x200)&&t.point(-1,0x20)&&t.session.storage_page()==ForceEditorStoragePage::Items,"B back and source R to Items");check(t.point(-1,0x800)&&t.session.list().phase()==ForceEditorListPhase::Sort,"actual Items Y sorting popup");t.wait();check(t.point(3,0x100)&&t.session.list().phase()==ForceEditorListPhase::Tribe,"Items tribe menu has no Borg copy/rename");t.wait();check(t.point(-1,0,4)&&t.session.list().menu_row()==1,"popup scroll arrow uses old navigation");check(t.point(2,0x100)&&t.session.list().phase()==ForceEditorListPhase::Browse&&t.session.list().tribes()==2,"visible tribe choice applies normal filter");}
    {Test t;check(t.open(),"paging session");for(unsigned n=0;n<23;++n)t.warehouse(n%6);check(t.session.step({},0,0x20)&&t.point(0,0x100),"multi-page actual instances");check(t.point(-1,0,2)&&t.session.warehouse_tools()->cursor()==10,"source right pages ten");check(!t.point(0,0x100)&&t.session.warehouse_tools()->cursor()==10,"offscreen stale row ordinal cannot activate");check(t.point(19)&&t.session.warehouse_tools()->cursor()==19&&t.point(-1,0,2)&&t.session.warehouse_tools()->cursor()==22,"last page clamps naturally");check(t.point(-1,0,1)&&t.session.warehouse_tools()->cursor()==12,"page-up normal path");auto c=t.session.list_mouse_context();Test neighbor;check(neighbor.open()&&neighbor.session.step({},0,0x20),"same metadata different owner");check(!neighbor.session.step({},0,0,{c,{-1,0x200,0}}),"foreign owner/session geometry cannot act");}
    {EditorMousePointer mouse;PointerState p;p.within_window=true;p.x=30;p.y=40;mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,false,1);p.left=true;check(mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,false,1).left_click,"fresh list click");check(!mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,false,2).left_click,"new modal consumes held click");check(!mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,false,2).left_click,"wait does not replay held click");p.left=false;mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,false,2);p.left=true;check(!mouse.update(p,640,480,EditorPointerContext::Lists,true,false,-1,true,2).left_click&&!mouse.mouse_mode(),"raw digital takes priority over simultaneous click");}
    std::printf("owned list/popup mouse scopes and native actions: %u checks PASS\n",checks);return 0;
}
